<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeKeyOptions;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Accessor\ConsentPurposeKeyAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ConsentPurposeKeyAccessor trait.
 *
 * Covers null default, string/VO assignment via withKey,
 * getKey/key accessors, and isKeyChanged with/without original.
 */
class ConsentPurposeKeyAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withKey creates a new instance with the Key set
     * from a string value, and getKey returns the primitive string.
     */
    public function testWithKeyFromString(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeKeyAccessorUnitTest();

        // Act
        $result = $holder->withKey(ConsentPurposeKeyOptions::MARKETING);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(ConsentPurposeKeyOptions::MARKETING, $result->getKey());
    }
    /**
     * Asserts that withkey has access to the value object
     * from a string value, and getKey returns the primitive string.
     */
    public function testWithKeyFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeKeyAccessorUnitTest();

        // Act
        $result = $holder->withKey(ConsentPurposeKeyOptions::MARKETING);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(ConsentPurposeKeyOptions::MARKETING, $result->key()->value());
    }
    public function testChangedKey(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeKeyAccessorUnitTest()->withKey(ConsentPurposeKeyOptions::MARKETING);
        $original = $holder->withKey(ConsentPurposeKeyOptions::MARKETING);
        $same = $holder->withKey(ConsentPurposeKeyOptions::MARKETING);
        $modified = $holder->withKey(ConsentPurposeKeyOptions::ANALYTICS);

        // Act
        $withSame = $original->isKeyChanged($same);
        $withDiferent = $original->isKeyChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithConsentPurposeKeyAccessorUnitTest
{
    use ConsentPurposeKeyAccessor;
}
